CREATE TYPE "UserStatus" AS ENUM ('INVITED','ACTIVE','SUSPENDED','DISABLED');
CREATE TYPE "MembershipStatus" AS ENUM ('INVITED','ACTIVE','SUSPENDED','ENDED');
CREATE TYPE "RoleScope" AS ENUM ('ORGANIZATION','PLATFORM');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"authProviderUserId" TEXT,"email" TEXT,"phone" TEXT,"status" "UserStatus" NOT NULL DEFAULT 'INVITED',"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_authProviderUserId_key" ON "User"("authProviderUserId"); CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "OrganizationMembership" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"status" "MembershipStatus" NOT NULL DEFAULT 'INVITED',"joinedAt" TIMESTAMP(3),"endedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Permission" ("id" TEXT PRIMARY KEY,"code" TEXT NOT NULL UNIQUE,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RoleDefinition" ("id" TEXT PRIMARY KEY,"organizationId" TEXT,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"scope" "RoleScope" NOT NULL,"isPlatformStandard" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "RolePermission" ("id" TEXT PRIMARY KEY,"roleDefinitionId" TEXT NOT NULL,"permissionId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("roleDefinitionId") REFERENCES "RoleDefinition"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("permissionId") REFERENCES "Permission"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "MembershipRole" ("id" TEXT PRIMARY KEY,"membershipId" TEXT NOT NULL,"roleDefinitionId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("membershipId") REFERENCES "OrganizationMembership"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("roleDefinitionId") REFERENCES "RoleDefinition"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "OrganizationMembership_userId_status_idx" ON "OrganizationMembership"("userId","status"); CREATE UNIQUE INDEX "OrganizationMembership_organizationId_userId_key" ON "OrganizationMembership"("organizationId","userId");
CREATE INDEX "RoleDefinition_code_isPlatformStandard_idx" ON "RoleDefinition"("code","isPlatformStandard"); CREATE UNIQUE INDEX "RoleDefinition_organizationId_code_key" ON "RoleDefinition"("organizationId","code");
CREATE UNIQUE INDEX "RolePermission_roleDefinitionId_permissionId_key" ON "RolePermission"("roleDefinitionId","permissionId"); CREATE UNIQUE INDEX "MembershipRole_membershipId_roleDefinitionId_key" ON "MembershipRole"("membershipId","roleDefinitionId");
